sys_script_client.script:
function onLoad() {
    var eventId = g_form.getValue('number'); // Gets current event record number

    var ga = new GlideAjax('GetEventDetails');
    ga.addParam('sysparm_name', 'getEventDetails');
    ga.addParam('sysparm_event_id', eventId);

    ga.getXMLAnswer(function(response) {
        var data = JSON.parse(response);

        if (data.error) {
            g_form.addInfoMessage('Error: ' + data.error);
        } else {
            // Populate form fields
            g_form.setValue('u_event_name', data.name);
            g_form.setValue('u_event_date', data.date);
            g_form.setValue('u_location', data.location);
            g_form.setValue('u_status', data.status);
            g_form.setValue('u_contact_person', data.contact);
            g_form.setValue('u_email', data.email);

            // Optional info message
            g_form.addInfoMessage('Event details loaded successfully.');
        }
    });
}
